/**
 * Plan nach ID. Neben CH_PLANS gibt es die Folge-Tarife eines Einmalkaufs (nicht einzeln kaufbar, nur mit Lizenz):
 *   betrieb-<x>  Betriebs-Abo (kind 'betrieb', inkl. Tokens/Monat)  ·  byok-<x>  eigener KI-Schlüssel (kind 'byok', Plattformgebühr, 0 Tokens)
 * mit <x> = Suffix des Einmalkaufs (buy-termine → betrieb-termine / byok-termine). Zusatzfelder: channels, category, license, tier.
 */
function ch_plan(string $id): ?array {
  if(preg_match('/^(betrieb|byok)-([a-z0-9-]+)$/',$id,$m)){
    $buy='buy-'.$m[2]; $tier=CH_BUY_TIER[$buy] ?? null; if(!isset(CH_PLANS[$buy],CH_PLAN_BASE[$buy]) || !$tier || !isset(CH_RUN_TIERS[$tier])) return null;
    $t=CH_RUN_TIERS[$tier]; $base=CH_PLAN_BASE[$buy]; $bn=trim((string)preg_replace('/\s*\(.*\)\s*$/u','',CH_PLANS[$base][0] ?? CH_PLANS[$buy][0]));
    $byok=$m[1]==='byok'; $cents=$byok ? $t['byok_cents'] : $t['betrieb_cents']; $tokens=$byok ? 0 : $t['betrieb_tokens'];
    $name=$byok ? 'Eigener KI-Schlüssel: '.$bn : 'Betrieb: '.$bn;
    $desc=$byok ? 'Plattformgebühr für '.$bn.' mit deinem eigenen Claude- oder DeepSeek-Schlüssel – Telefon, WhatsApp, Web-Chat, Studio, Updates und Support; KI-Kosten zahlst du direkt beim Anbieter, ChatHelp bucht dafür keine Tokens ab'
               : 'Laufender Betrieb für '.$bn.' nach dem Einmalkauf – inkl. '.number_format($tokens,0,',','.').' Tokens/Monat, Telefon, WhatsApp, Web-Chat, Studio, Updates und Support; nicht verbrauchte Tokens bleiben';
    return ['id'=>$id,'name'=>$name,'cents'=>$cents,'tokens'=>$tokens,'sector'=>CH_PLANS[$buy][3],'kind'=>$m[1],'desc'=>$desc,'rules'=>CH_AGENT_RULES[$base] ?? '','base'=>$base,
      'license'=>$buy,'tier'=>$tier,'channels'=>ch_plan_channels($base),'category'=>ch_plan_category($buy)];
  }
  if(!isset(CH_PLANS[$id])) return null;
  [$name,$cents,$tokens,$sector,$kind,$desc] = CH_PLANS[$id];
  /* Anpassung durch den Betreiber (Studio → Preise, ch_settings 'plan_overrides'): gilt für neue Käufe – Bestandsabos behalten Preis und Tokens (Stripe-Preis, Abo-Metadaten) */
  $ov=function_exists('ch_setting') ? (ch_setting('plan_overrides',[])[$id] ?? null) : null;
  if(is_array($ov)){ if(isset($ov['cents']) && (int)$ov['cents']>=100) $cents=(int)$ov['cents']; if(isset($ov['tokens']) && (int)$ov['tokens']>=0) $tokens=(int)$ov['tokens']; }
  $base = CH_PLAN_BASE[$id] ?? $id;
  $o=['id'=>$id,'name'=>$name,'cents'=>$cents,'tokens'=>$tokens,'sector'=>$sector,'kind'=>$kind,'desc'=>$desc,'rules'=>CH_AGENT_RULES[$id] ?? (CH_AGENT_RULES[$base] ?? ''),'base'=>$base,
    'channels'=>ch_plan_channels($id),'category'=>ch_plan_category($id) ?? ($base!==$id ? ch_plan_category($base) : null)];
  if(($t=ch_plan_tier($id))!==null){ $o['tier_key']=$t['key']; $o['tier_of']=$t['base']; }
  if($kind==='buy'){ $o['tier']=CH_BUY_TIER[$id] ?? null; $o['included_days']=ch_buy_included_days($id); if(isset(CH_BUY_TERMS[$id])) $o['terms']=CH_BUY_TERMS[$id]; }
  return $o;
}
/* Einmalkauf-Pakete → zugrunde liegender Agent (Rolle/Vorlagen) */
const CH_PLAN_BASE = ['buy-website'=>'agent-website','buy-support'=>'agent-support','buy-content'=>'agent-content','buy-phone'=>'agent-phone','buy-inkasso'=>'agent-inkasso','buy-kanzlei'=>'agent-kanzlei','buy-steuer'=>'agent-steuer','buy-termine'=>'agent-termine','buy-bestellung'=>'agent-bestellung','buy-taxi'=>'agent-taxi','buy-hotel'=>'agent-hotel',
  'buy-beauty'=>'agent-beauty','buy-aesthetic'=>'agent-aesthetic','buy-hair-tr'=>'agent-hair-tr','buy-dental-tr'=>'agent-dental-tr','buy-marketing'=>'agent-marketing','buy-amazon-fba'=>'agent-amazon',
  'agent-phone-s'=>'agent-phone','agent-phone-l'=>'agent-phone','agent-hotel-s'=>'agent-hotel','agent-hotel-l'=>'agent-hotel'];
/** Stufen eines Agenten (klein → groß): gleicher Agent, gleiche Einrichtung, mehr Gesprächszeit. Upgrade im Studio (bl_plan_upgrade). */
const CH_PLAN_TIERS = ['agent-phone'=>['agent-phone-s','agent-phone','agent-phone-l'],'agent-hotel'=>['agent-hotel-s','agent-hotel','agent-hotel-l']];
const CH_TIER_LABELS = ['s'=>'Klein','m'=>'Standard','l'=>'Intensiv'];
/** Stufen-Kennung eines Plans: ['base','key'=>s|m|l,'ids'=>[…]] oder null. */
function ch_plan_tier(string $id): ?array {
  foreach(CH_PLAN_TIERS as $base=>$ids){ $i=array_search($id,$ids,true); if($i!==false) return ['base'=>$base,'key'=>['s','m','l'][$i] ?? 'm','ids'=>$ids,'next'=>$ids[$i+1] ?? null]; }
  return null;
}

/* ---- Preise nach dem Einmalkauf: Betrieb (inkl. Tokens) oder eigener KI-Schlüssel (BYOK) ---- */
/** So viele Tage Betrieb sind im Einmalkauf enthalten (danach Betrieb- oder BYOK-Abo). Bestandskäufe ohne Enddatum bleiben unbefristet. */
const CH_BUY_INCLUDED_DAYS = 90;
/** Lizenzen mit Laufzeitwahl: term => Preis (EUR-Cent) und enthaltene Betriebstage. Term 1 = Katalogpreis. USD-Festpreise: CH_LOCAL_PRICE_FIX (i18n.php). */
const CH_BUY_TERMS = ['buy-amazon-fba'=>[1=>['cents'=>86000,'days'=>365,'label'=>'1 Jahr'],2=>['cents'=>155000,'days'=>730,'label'=>'2 Jahre']]];
/** Enthaltene Betriebstage eines Einmalkaufs (Laufzeitwahl, sonst CH_BUY_INCLUDED_DAYS). */
function ch_buy_included_days(string $id, int $term=1): int {
  $t=CH_BUY_TERMS[$id] ?? null; if(!$t) return CH_BUY_INCLUDED_DAYS;
  return (int)($t[$term]['days'] ?? $t[1]['days']);
}
/** Laufzeit-Angebot: ['term','cents','days','label'] oder null, wenn der Plan keine Laufzeitwahl hat bzw. der Term unbekannt ist. */
function ch_buy_term(string $id, int $term): ?array {
  $t=CH_BUY_TERMS[$id][$term] ?? null; return $t ? ['term'=>$term]+$t : null;
}
/** Stufen der Folge-Abos (Cent/Monat netto, Tokens/Monat). S = Website-/Content-Bots, M = Termine/Bestellung/Taxi, L = Telefon/Hotel/Kanzlei/Steuer/Inkasso. */
const CH_RUN_TIERS = [
  'S' => ['label'=>'Basis',    'betrieb_cents'=>1900, 'betrieb_tokens'=>4000, 'byok_cents'=>900],
  'M' => ['label'=>'Standard', 'betrieb_cents'=>2900, 'betrieb_tokens'=>6000, 'byok_cents'=>1400],
  'L' => ['label'=>'Profi',    'betrieb_cents'=>3900, 'betrieb_tokens'=>8000, 'byok_cents'=>1900],
];
const CH_BUY_TIER = ['buy-website'=>'S','buy-content'=>'S','buy-support'=>'S','buy-termine'=>'M','buy-bestellung'=>'M','buy-taxi'=>'M',
  'buy-phone'=>'L','buy-hotel'=>'L','buy-kanzlei'=>'L','buy-steuer'=>'L','buy-inkasso'=>'L','buy-beauty'=>'M','buy-aesthetic'=>'L','buy-hair-tr'=>'L','buy-dental-tr'=>'L','buy-marketing'=>'M','buy-amazon-fba'=>'L'];
/** Folge-Tarife eines Einmalkaufs: ['betrieb'=>plan,'byok'=>plan] (leer, wenn kein Einmalkauf). */
function ch_followups(string $buyId): array {
  if(!str_starts_with($buyId,'buy-') || !isset(CH_PLANS[$buyId])) return [];
  $x=substr($buyId,4); return array_filter(['betrieb'=>ch_plan('betrieb-'.$x),'byok'=>ch_plan('byok-'.$x)]);
}
/** Lizenz (Einmalkauf) zu einem Plan/Agenten: buy-x für agent-x, betrieb-x, byok-x, buy-x; sonst null. */
function ch_plan_license(string $id): ?string {
  if(preg_match('/^(?:betrieb|byok|buy)-([a-z0-9-]+)$/',$id,$m) && isset(CH_PLANS['buy-'.$m[1]])) return 'buy-'.$m[1];
  $buy=array_search($id,CH_PLAN_BASE,true); return $buy===false ? null : (string)$buy;
}
/** Alle IDs, die denselben Agenten freischalten: Monatsplan (alle Stufen), Einmalkauf, Betrieb, eigener Schlüssel. */
function ch_plan_variants(string $id): array {
  $p=ch_plan($id); $base=$p ? (string)$p['base'] : $id; $ids=[$id,$base];
  if(isset(CH_PLAN_TIERS[$base])) array_push($ids,...CH_PLAN_TIERS[$base]);
  if(($lic=ch_plan_license($base) ?? ch_plan_license($id))!==null){ $x=substr($lic,4); array_push($ids,$lic,'betrieb-'.$x,'byok-'.$x); }
  return array_values(array_unique($ids));
}

/* ---- Kanäle je Tarif: jeder Agent mit Kundenkontakt = Telefon + WhatsApp + Web-Chat; reine Website-Bots und Content-Pakete = nur Web ---- */
const CH_CHANNELS = ['web'=>['label'=>'Web-Chat & Widget','icon'=>'💬'],'phone'=>['label'=>'Telefon','icon'=>'☎'],'whatsapp'=>['label'=>'WhatsApp','icon'=>'🟢'],
  'phone_out'=>['label'=>'Anrufe für dich','icon'=>'📞']];
/** Reine Website-Bots (kind 'agent', aber ohne Telefon/WhatsApp). Alle kind 'abo' sind ebenfalls nur Web. */
const CH_WEB_ONLY = ['agent-support','ec-support','log-support','agent-website','agent-content','agent-marketing','agent-amazon'];   // Marketing/Amazon: arbeiten für das Team im Studio (kein Telefon/WhatsApp)
/** Ausnahmen mit eigener Kanal-Liste (phone_out = nur ausgehende, einzeln bestätigte Anrufe). */
const CH_PLAN_CHANNELS = ['privat-anruf'=>['web','phone_out']];
/** Kanäle eines Plans (Einmalkauf/Betrieb/BYOK erben vom Agenten). Unbekannt → ['web']. */
function ch_plan_channels(string $id): array {
  if(preg_match('/^(?:betrieb|byok)-([a-z0-9-]+)$/',$id,$m)) $id=CH_PLAN_BASE['buy-'.$m[1]] ?? $id;
  $id=CH_PLAN_BASE[$id] ?? $id;
  if(isset(CH_PLAN_CHANNELS[$id])) return CH_PLAN_CHANNELS[$id];
  if(!isset(CH_PLANS[$id]) || CH_PLANS[$id][4]!=='agent' || in_array($id,CH_WEB_ONLY,true)) return ['web'];
  return ['web','phone','whatsapp'];
}
/** Deckt der Plan den Kanal ab? phone schließt ausgehende Anrufe (KI-Rückruf, phone_out) ein; studio/demo/api/web/widget = web. */
function ch_plan_has_channel(string $id, string $channel): bool {
  $ch=ch_plan_channels($id);
  $c=match($channel){ 'whatsapp'=>'whatsapp', 'phone'=>'phone', 'phone_out'=>'phone_out', default=>'web' };
  return in_array($c,$ch,true) || ($c==='phone_out' && in_array('phone',$ch,true));
}

/* ---- Telefon-Grenzen je Paket (Studio → Einstellungen des Betreibers: ch_settings 'phone_limits') ---- */
const CH_PHONE_LIMITS_DEFAULT = ['max_call_min'=>10,'concurrent'=>2];
/** ['max_call_sec','concurrent'] für einen Plan: Standard 10 Minuten und 2 gleichzeitige Gespräche, je Plan überschreibbar (concurrent_by_plan). */
function ch_phone_limits(string $plan): array {
  $s=function_exists('ch_setting') ? (array)ch_setting('phone_limits',[]) : []; $p=function_exists('ch_plan') ? ch_plan($plan) : null; $base=(string)($p['base'] ?? $plan);
  $min=(int)($s['max_call_min'] ?? CH_PHONE_LIMITS_DEFAULT['max_call_min']); $c=$s['concurrent_by_plan'][$plan] ?? ($s['concurrent_by_plan'][$base] ?? ($s['concurrent'] ?? CH_PHONE_LIMITS_DEFAULT['concurrent']));
  return ['max_call_sec'=>max(2,min(60,$min))*60,'concurrent'=>max(1,min(30,(int)$c))];
}
/**
 * Tokens je Telefon-Antwort (im Studio änderbar: ch_settings 'phone_rates'): ChatHelp-Nummer 12 (Twilio zahlt ChatHelp), eigenes Twilio-Konto 9.
 * Bestandsschutz: Paket vor dem Stichtag (ch_phone_rate_since) gebucht → weiter 8 (CH_PRICING['phone_turn']), egal über welche Nummer, bis der Kunde selbst wechselt.
 */
/** Stichtag der neuen Sätze: wird beim ersten Aufruf nach dem Deploy in ch_settings gemerkt (Datenbankzeit wie token_plans.created_at). */
function ch_phone_rate_since(): string {
  $s=function_exists('ch_setting') ? (string)ch_setting('phone_rate_since','') : ''; if($s!=='') return $s;
  try{ $s=(string)th_db()->query("SELECT NOW()")->fetchColumn(); ch_setting_set('phone_rate_since',$s); }catch(Throwable $e){ $s=date('Y-m-d H:i:s'); }
  return $s;
}
/** premium = Aufpreis je Antwort für die Premium-Stimme (ElevenLabs) am Telefon. */
function ch_phone_rates(): array { $r=function_exists('ch_setting') ? (array)ch_setting('phone_rates',[]) : []; return ['central'=>max(1,(int)($r['central'] ?? 12)),'own'=>max(1,(int)($r['own'] ?? 9)),'legacy'=>max(1,(int)($r['legacy'] ?? CH_PRICING['phone_turn'])),'premium'=>max(0,(int)($r['premium'] ?? 6))]; }
/** Bestandskunde für diesen Agenten (Plan vor Einführung der neuen Telefontarife gebucht) → alter Tarif und bisherige Stimmen. */
function ch_phone_legacy(int $acc, string $plan): bool {
  if($acc<=0 || !function_exists('th_db')) return false;
  try{ $ids=ch_plan_variants($plan); $s=th_db()->prepare("SELECT MIN(created_at) FROM token_plans WHERE account_id=? AND plan IN (".implode(',',array_fill(0,count($ids),'?')).") AND status IN ('active','trialing','past_due','license')");
    $s->execute(array_merge([$acc],$ids)); $first=(string)($s->fetchColumn() ?: ''); return $first!=='' && $first<ch_phone_rate_since(); }catch(Throwable $e){ return false; }
}
function ch_phone_turn_tokens(int $acc, string $plan): int {
  $r=ch_phone_rates(); if($acc<=0 || !function_exists('th_secret')) return $r['central'];
  if(ch_phone_legacy($acc,$plan)) return $r['legacy'];
  return th_secret($acc,'twilio_token')==='' ? $r['central'] : $r['own'];   // ohne eigenes Twilio läuft der Anruf über das Plattform-Konto (ChatHelp-Nummer)
}
