const CH_PHONE_SECTOR_CATEGORY = ['restaurant'=>'bestellung','taxi'=>'mobilitaet','cafe'=>'gastro','hotel'=>'gastro','friseur'=>'dienstleistung','fitness'=>'dienstleistung',
  'autowerkstatt'=>'dienstleistung','handwerk'=>'dienstleistung','stadtwerke'=>'oeffentlich','zahnarzt'=>'gesundheit','arztpraxis'=>'gesundheit','tierarzt'=>'gesundheit',
  'apotheke'=>'gesundheit','beauty'=>'beauty','aesthetic'=>'beauty','hair-tr'=>'medtour','dental-tr'=>'medtour','bank'=>'finanzen','versicherung'=>'finanzen','kanzlei'=>'recht','steuerberater'=>'recht','hausverwaltung'=>'immobilien','immobilien'=>'immobilien'];
/** Kategorie eines Plans (Folge-Tarife: Kategorie des Einmalkaufs). null = keiner zugeordnet (Test fängt das ab). */
function ch_plan_category(string $id): ?string {
  static $map=null;
  if($map===null){ $map=[]; foreach(CH_CATEGORIES as $cid=>$c) foreach($c['plans'] as $p) $map[$p] ??= $cid; }
  if(preg_match('/^(?:betrieb|byok)-([a-z0-9-]+)$/',$id,$m)) $id='buy-'.$m[1];
  return $map[$id] ?? null;
}
/** Kategorie zu einem Gruppennamen der Startseite (z. B. „Finanzen & Recht“ → ['finanzen','recht']). */
function ch_home_group_categories(string $group): array {
  return array_keys(array_filter(CH_CATEGORIES,fn($c)=>($c['home_group'] ?? null)===$group));
}
/**
 * Öffentliche Kategorienliste (GET /v1/categories): Kategorien in Reihenfolge, je Plan id, name, price (€), kind, channels, demo (CH_DEMO-Schlüssel oder null),
 * bei Einmalkäufen die Folge-Tarife (Betrieb / eigener Schlüssel); dazu die Telefon-Branchen der Startseite je Kategorie.
 */
function ch_categories_public(): array {
  $cats=CH_CATEGORIES; uasort($cats,fn($a,$b)=>$a['order']<=>$b['order']); $out=[];
  $phone=[]; foreach(CH_PHONE_SECTORS as $k=>$s){ $c=CH_PHONE_SECTOR_CATEGORY[$k] ?? null; if($c) $phone[$c][]=['key'=>$k,'label'=>$s['label'],'icon'=>$s['icon'] ?? '☎']; }
  foreach($cats as $cid=>$c){
    $plans=[];
    foreach($c['plans'] as $pid){ $p=ch_plan($pid); if(!$p) continue;
      $row=['id'=>$pid,'name'=>$p['name'],'price'=>$p['cents']/100,'price_cents'=>$p['cents'],'interval'=>$p['kind']==='buy' ? 'once' : 'month','tokens'=>$p['tokens'],'kind'=>$p['kind'],
        'sector'=>$p['sector'],'desc'=>$p['desc'],'channels'=>$p['channels'],'demo'=>isset(CH_DEMO[$p['base']]) ? $p['base'] : null,'base'=>$p['base']];
      if($p['kind']==='buy'){ $row['included_days']=ch_buy_included_days($pid); if(isset($p['terms'])) $row['terms']=array_map(fn($t)=>['price'=>$t['cents']/100,'price_cents'=>$t['cents'],'days'=>$t['days'],'label'=>$t['label']],$p['terms']); foreach(ch_followups($pid) as $k=>$f) $row['followups'][$k]=['id'=>$f['id'],'name'=>$f['name'],'price'=>$f['cents']/100,'price_cents'=>$f['cents'],'interval'=>'month','tokens'=>$f['tokens'],'kind'=>$f['kind']]; }
      elseif(($lic=ch_plan_license($pid))!==null) $row['one_time']=$lic;
      $plans[]=$row; }
    $out[]=['id'=>$cid,'label'=>$c['label'],'short'=>$c['short'],'icon'=>$c['icon'],'order'=>$c['order'],'home_group'=>$c['home_group'],'plans'=>$plans,'phone_sectors'=>$phone[$cid] ?? []];
  }
  return $out;
}

/**
 * Demo-Konfiguration für einen Agenten (Fallback: Muster-Firma). $raw = eigene Rohdaten (z. B. eine Branche des Telefon-Agenten) statt CH_DEMO[$plan].
 * Liefert immer persona, style, voice{preset,gender,rate,pitch,role,instructions}, fillers[], chips[], script[[role,text]], du.
 */
function ch_demo_cfg(string $plan, ?array $raw=null): array {
  $d = $raw ?? (CH_DEMO[$plan] ?? ['company'=>'Muster GmbH','tone'=>'freundlich-professionell','lang'=>'de','persona'=>'Alex','du'=>true,'voice'=>['preset'=>'m_freundlich'],
    'greeting'=>'Hallo, hier ist Alex, der Demo-Agent der Muster GmbH. Was kann ich für dich tun?','chips'=>['Was kannst du?','Wie funktioniert die Einrichtung?'],
    'kb'=>"Muster GmbH, Musterstraße 1, 10115 Berlin. Öffnungszeiten Mo–Fr 9–17 Uhr. Kontakt: info@muster.de. Leistungen: Beratung, Service, Support.",
    'script'=>[['a','Hallo, hier ist Alex, der Demo-Agent der Muster GmbH. Was kann ich für dich tun?'],['u','Wann habt ihr geöffnet?'],['a','Montag bis Freitag von 9 bis 17 Uhr – soll ich dir noch etwas zu unseren Leistungen sagen?']]]);
  /* Mehrsprachige Begrüßung (z. B. Kliniken in der Türkei): Sprache aus ?lang=, JSON-Feld lang oder Accept-Language – nur wenn eine Übersetzung hinterlegt ist */
  if(is_array($d['greetings'] ?? null) && $d['greetings']){ $rl=ch_demo_req_lang();
    if($rl!=='' && isset($d['greetings'][$rl])){ $old=(string)($d['greeting'] ?? ''); $d['greeting']=(string)$d['greetings'][$rl]; $d['lang']=$rl;
      foreach((array)($d['script'] ?? []) as $i=>$row){ if(is_array($row) && $row && end($row)===$old){ $d['script'][$i][count($row)-1]=$d['greeting']; break; } } }
    $d['languages']=array_keys($d['greetings']); }
  /* Stimme: Voreinstellung (speech-lib ch_tts_voices) + Persona-Feinschliff; Geschlecht folgt der Voreinstellung */
  $v = is_array($d['voice'] ?? null) ? $d['voice'] : [];
  $pid = (string)($v['preset'] ?? '');
  if(preg_match('/^([fm])_[a-z0-9_]{2,30}$/', $pid, $pm)) $g = $pm[1];
  else { $g = ($v['gender'] ?? 'f') === 'm' ? 'm' : 'f'; $pid = $g === 'm' ? 'm_freundlich' : 'f_warm'; }
  $num = fn($x, float $def): float => is_numeric($x) ? (float)$x : $def;
  $d['voice'] = ['preset'=>$pid, 'gender'=>$g,
    'rate'=>round(max(0.85, min(1.15, $num($v['rate'] ?? null, 1.0))), 2), 'pitch'=>round(max(0.8, min(1.2, $num($v['pitch'] ?? null, 1.0))), 2),
    'role'=>trim((string)($v['role'] ?? '')), 'instructions'=>trim((string)($v['instructions'] ?? ''))];
  $d['fillers'] = array_values(array_filter(array_map('strval', (array)($d['fillers'] ?? [])), fn($f)=>trim($f)!=='')) ?: ['Einen Moment bitte, ich schaue kurz nach.','Augenblick, ich prüfe das gerade.'];
  $d['chips'] = array_values(array_filter(array_map('strval', (array)($d['chips'] ?? [])), fn($c)=>trim($c)!==''));
  $d += ['persona'=>'','du'=>false,'greeting'=>'','company'=>'','kb'=>'','tone'=>'freundlich-professionell','lang'=>'de',
    'style'=>'Freundlich, klar und natürlich – wie eine erfahrene Mitarbeiterin oder ein erfahrener Mitarbeiter genau dieses Betriebs. Kurze Sätze, eine Frage pro Antwort, wichtige Angaben wiederholen und bestätigen lassen. Bei Ärger zuerst Verständnis zeigen, dann eine konkrete Lösung anbieten; bei Notfällen sofort auf 112 bzw. den Notdienst verweisen. Keine Floskeln, nichts erfinden.'];
  /* Beispielgespräch (Autoplay): [[role,text],…] mit role a|u|sys; [step,role,text] wird ebenfalls akzeptiert */
  $sc = [];
  foreach((array)($d['script'] ?? []) as $row){
    if(!is_array($row) || count($row) < 2) continue; $row = array_values($row); $n = count($row);
    $r = (string)$row[$n-2]; $t = trim(str_replace('\\n', "\n", (string)$row[$n-1]));   // literales \n aus Demo-Texten → Zeilenumbruch
    if(in_array($r, ['a','u','sys'], true) && $t !== '') $sc[] = [$r, $t];
  }
  $d['script'] = $sc ?: ($d['greeting'] !== '' ? [['a', (string)$d['greeting']]] : []);
  return $d + ['widget_key'=>null,'widget_domain'=>'','widget_on'=>0];
}
/** Gewünschte Sprache der Demo-Anfrage (2 Buchstaben): ?lang= → JSON-Feld lang → Accept-Language; '' = unbekannt. */
function ch_demo_req_lang(): string {
  static $body=null;
  $v=$_GET['lang'] ?? null;
  if(!is_string($v) || $v===''){ if($body===null){ $raw=PHP_SAPI==='cli' ? '' : (string)@file_get_contents('php://input'); $j=$raw!=='' ? json_decode($raw,true) : null; $body=is_array($j) && is_string($j['lang'] ?? null) ? $j['lang'] : ''; } $v=$body; }
  if($v==='') $v=(string)($_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? '');
  return substr((string)preg_replace('/[^a-z]/','',strtolower(substr($v,0,2))),0,2);
}
/** Branche des Telefon-Agenten → Konfiguration wie ch_demo_cfg + sector, label, icon, group, tools[], sector_sys, rules_from, services[], address. Unbekannt → zahnarzt. */
function ch_phone_sector_cfg(string $key=''): array {
  $k = isset(CH_PHONE_SECTORS[$key]) ? $key : 'zahnarzt';
  $s = CH_PHONE_SECTORS[$k];
  $base = (isset($s['from_demo']) && isset(CH_DEMO[$s['from_demo']])) ? CH_DEMO[$s['from_demo']] : [];
  $raw = array_merge($base, $s);
  if(isset($base['voice'], $s['voice']) && is_array($base['voice']) && is_array($s['voice'])) $raw['voice'] = array_merge($base['voice'], $s['voice']);
  unset($raw['from_demo']);
  $d = ch_demo_cfg('agent-phone', $raw);
  $d['sector'] = $k;
  $d += ['label'=>$k,'icon'=>'☎','group'=>'Dienstleistung','tools'=>['callback'],'sector_sys'=>'service','rules_from'=>'','services'=>[],'address'=>''];
  $d['tools'] = array_values(array_filter((array)$d['tools'], 'is_string'));
  $d['services'] = array_values(array_filter((array)$d['services'], fn($x)=>is_array($x) && trim((string)($x['name'] ?? ''))!=='' && (int)($x['duration_min'] ?? 0)>0));
  return $d;
}
